Unit tests for the mobile app

### Test Suite: Book Feature

## 1. Project setup

Run the following command to generate the test coverage report:

```bash
npm test
```

If your project uses Jest, add `setupTests.ts` to the test root and include:

```ts
import 'jest-dom/extend-expect';
```

## 2. Test setup

Create a test fixture for a new book:

```ts
import Book from '../src/types/book';

describe('Book', () => {
  const newBook: Book = {
    id: 'new-book-123',
    title: 'New Book Title',
    author: 'Author Name',
    status: 'Draft',
    lastModified: new Date().toISOString(),
    createdAt: new Date().toISOString(),
    pages: 100,
    categories: ['fiction', 'science-fantasy'],
    readingProgress: 25,
    lastReadDate: null,
    coverImage: 'https://example.com/cover.png',
    description: 'A new book title that describes a fictional story.',
    language: 'English',
    isPublished: false,
    isAvailable: true,
    publishedAt: null,
    publisher: 'Example Publisher',
    isbn: '978-0-000-00000-0',
  };
});
```

## 3. Basic functionality tests

### 3.1. Create a new book

```ts
describe('Create a new book', () => {
  it('creates a book with the given title, author, status, and lastModified timestamp', () => {
    const result = createBook(newBook);

    expect(result).toBeDefined();
    expect(result.id).toBe('new-book-123');
    expect(result.title).toBe(newBook.title);
    expect(result.author).toBe(newBook.author);
    expect(result.status).toBe(newBook.status);
    expect(result.lastModified).toEqual(newBook.lastModified);
  });
});
```

### 3.2. Update a book

```ts
describe('Update a book', () => {
  it('updates the book title, author, status, and lastModified timestamp', () => {
    const result = updateBook(newBook);

    expect(result).toBeDefined();
    expect(result.id).toBe(newBook.id);
    expect(result.title).toBe(newBook.title);
    expect(result.author).toBe(newBook.author);
    expect(result.status).toBe(newBook.status);
    expect(result.lastModified).toEqual(newBook.lastModified);
  });
});
```

### 3.3. Delete a book

```ts
describe('Delete a book', () => {
  it('deletes the book and sets its status to deleted', () => {
    const result = deleteBook(newBook);

    expect(result).toBeDefined();
    expect(result.id).toBe(newBook.id);
    expect(result.status).toBe('deleted');
  });
});
```

### 3.4. Check whether a book exists

```ts
describe('Check whether a book exists', () => {
  it('returns true when the book exists and false when it does not', () => {
    const result = existsBook(newBook);

    expect(result).toBe(true);
  });
});
```

### 3.5. Get book metadata

```ts
describe('Get book metadata', () => {
  it('returns title, author, and status for a book', () => {
    const result = getBookMetadata(newBook);

    expect(result).toBeDefined();
    expect(result.title).toBe(newBook.title);
    expect(result.author).toBe(newBook.author);
    expect(result.status).toBe(newBook.status);
  });
});
```

### 3.6. Get book cover image

```ts
describe('Get book cover image', () => {
