## 4. Data integrity tests

### 4.1. Validate book creation

```ts
describe('Validate book creation', () => {
  it('rejects a book with an invalid title', () => {
    const result = createBook({
      ...newBook,
      title: '',
    });

    expect(result).toBeDefined();
  });

  it('rejects a book with an empty author', () => {
    const result = createBook({
      ...newBook,
      author: '',
    });

    expect(result).toBeDefined();
  });

  it('rejects a book with a status that is not Draft, Published, or Available', () => {
    const result = createBook({
      ...newBook,
      status: 'Unknown',
    });

    expect(result).toBeDefined();
  });

  it('rejects a book with a status that is not Draft, Published, or Available', () => {
    const result = createBook({
      ...newBook,
      status: 'Cancelled',
    });

    expect(result).toBeDefined();
  });
});
```

